#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<int> f={2,0,1,3};
int n=4;vector<int> freq(n,0);
bool valid=true;
for(int y:f){if(y<0||y>=n)valid=false;else freq[y]++;}
bool injective=valid,surjective=valid;
for(int count:freq){if(count>1)injective=false;if(count==0)surjective=false;}
cout<<injective<<" "<<surjective<<" "<<(injective&&surjective)<<"\n";
return 0;
}

